<script setup lang="ts">
import { computed, ref } from 'vue';
import { useDispatchStore } from '../stores/dispatch';
const store=useDispatchStore(),data=ref<any>(null),selected=ref<any>(null),reason=ref(''),confirmation=ref(''),clear=ref(false),comment=ref(''),busy=ref(false),error=ref(''),message=ref('');
const leases=computed(()=>data.value?.resources.flatMap((r:any)=>r.leases)??[]);
async function run(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';try{await fn();}catch(e){error.value=e instanceof Error?e.message:String(e);}finally{busy.value=false;}}
async function read(){data.value=await store.api('/api/resource-review');selected.value=null;clear.value=false;confirmation.value='';}
function load(){void run(read);}
async function submit(){if(!selected.value)return;await run(async()=>{const result:any=await store.api('/api/resource-review/submit',{leaseId:selected.value.leaseId,reason:reason.value,vehicleClearConfirmed:clear.value,confirmationText:confirmation.value});message.value=result.message;await read();});}
async function review(requestId:string,approve:boolean){await run(async()=>{const result:any=await store.api('/api/resource-review/review',{requestId,approve,comment:comment.value});message.value=result.message;await read();});}
</script>
<template><section class="management-page resource-review"><header class="management-title"><h2>原占用与资源处置</h2><RouterLink to="/recovery">返回任务与启动恢复</RouterLink></header><p>先查询原任务、原命令和车辆实际位置。任务取消不自动释放路权；资源到期也不代表现场已清空。所有申请及复核沿用后台权限与审计规则。</p><button :disabled="busy||store.demoMode||store.engineeringSimulationOnly" @click="load">读取当前占用与申请</button><p v-if="error" class="inline-warning" role="alert">{{error}}</p><p role="status">{{message}}</p><template v-if="data"><p>当前操作身份：{{data.session?.displayName}} · {{data.enabled?'资源处置入口已启用':'只读'}} </p><div class="resource-scroll"><table><thead><tr><th>资源</th><th>车辆 / 原任务</th><th>步骤 / 状态</th><th>操作</th></tr></thead><tbody><tr v-for="lease in leases" :key="lease.leaseId"><td>{{lease.resourceId}}</td><td>{{lease.vehicleId}}<br/><RouterLink :to="'/tasks/'+lease.taskId">{{lease.taskId}}</RouterLink></td><td>{{lease.ownerStepId}}<br/>{{lease.taskStage}} · {{lease.heartbeatExpired?'心跳过期，仍保留占用':'占用中'}}</td><td><button :disabled="!data.enabled||busy" @click="selected=lease;clear=false;confirmation='';reason=''">核对并申请处置</button></td></tr><tr v-if="!leases.length"><td colspan="4">后台未返回当前占用。</td></tr></tbody></table></div>
<fieldset v-if="selected"><legend>{{selected.resourceId}} / {{selected.vehicleId}}</legend><p>原租约{{selected.leaseId}}。本操作只申请释放所选占用，不补记任务完成，不发送车辆动作。</p><label>现场依据<textarea v-model="reason" placeholder="填写车辆位置、区域清空、原任务与设备交接核对情况"/></label><label><input v-model="clear" type="checkbox"/>现场已确认车辆及载荷完全离开此资源区域</label><label>输入 RELEASE {{selected.resourceId}}<input v-model="confirmation"/></label><button :disabled="busy||!clear||reason.trim().length<10||confirmation!=='RELEASE '+selected.resourceId" @click="submit">提交原占用处置申请</button><button @click="selected=null">取消编辑</button></fieldset>
<h3>申请与复核</h3><label>复核说明<input v-model="comment" placeholder="填写本次复核依据"/></label><article v-for="r in data.requests" :key="r.requestId"><b>{{r.resourceId}} · {{r.status}}</b><p>{{r.reason}} · {{r.requestedByDisplayName}}</p><button v-if="r.status==='PendingApproval'" :disabled="busy||!data.enabled||comment.trim().length<10" @click="review(r.requestId,true)">按后台规则复核通过</button><button v-if="r.status==='PendingApproval'" :disabled="busy||!data.enabled||comment.trim().length<10" @click="review(r.requestId,false)">拒绝申请</button></article><h3>释放审计</h3><p v-for="a in data.audits" :key="a.auditId">{{a.releasedAt}} · {{a.resourceId}} · {{a.operator}} · {{a.reason}}</p></template></section></template>
<style scoped>.resource-review p{line-height:1.8}.resource-review a{color:#8ad5e5}.resource-scroll{overflow:auto;margin:20px 0}.resource-review table{width:100%;border-collapse:collapse;font-size:13px}.resource-review td,.resource-review th{padding:14px;text-align:left;border-bottom:1px solid #2d4260;overflow-wrap:anywhere;max-width:400px}.resource-review fieldset{padding:22px;border:1px solid #37516e;margin:22px 0}.resource-review label{display:grid;gap:10px;margin:14px 0}.resource-review textarea{min-height:80px}.resource-review button{margin:5px}.resource-review article{padding:14px;border-bottom:1px solid #2d4260}</style>
